import{_ as l,W as i,s as o,u as d,ah as r,I as t,w as e,Z as n,A as p}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const w=JSON.parse('{"title":"如何在 RHEL 9 上创建本地 Yum/DNF 仓库 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 9 上创建本地 Yum/DNF 仓库 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 RHEL 9 上创建本地 Yum/DNF 仓库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 9 上创建本地 Yum/DNF 仓库 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220601 How to Create Local Yum-DNF Repository on RHEL 9","title":"如何在 RHEL 9 上创建本地 Yum/DNF 仓库","tag":"202206"},"relativePath":"202206/20220601 How to Create Local Yum-DNF Repository on RHEL 9.md","filePath":"[post].md"}'),c={name:"202206/20220601 How to Create Local Yum-DNF Repository on RHEL 9.md"};function u(m,a,h,g,b,v){const s=i("Link");return d(),o("div",null,[a[15]||(a[15]=r(`<h1 id="如何在-rhel-9-上创建本地-yum-dnf-仓库" tabindex="-1">如何在 RHEL 9 上创建本地 Yum/DNF 仓库 <a class="header-anchor" href="#如何在-rhel-9-上创建本地-yum-dnf-仓库" aria-label="Permalink to 如何在 RHEL 9 上创建本地 Yum/DNF 仓库">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/11/164149y9zzm7kkxwsxgszw.jpg" alt=""></p><p>你好，技术兄弟，最近红帽发布了最新的操作系统 RHEL 9，RHEL 9 满足了混合云的所有要求。它可以安装在物理服务器、虚拟机和容器镜像中。</p><p>当我们没有订阅的时候，想安装软件包来做实验，那么设置本地的 Yum 或 DNF 仓库将是很方便的。</p><p>在本指南中，我们将介绍如何在 RHEL 9 上使用 DVD 或 ISO 文件一步一步地创建本地 Yum/DNF 资源库。</p><p>创建本地 Yum/DNF 资源库的先决条件:</p><ul><li>最小化安装 RHEL 9 系统</li><li>具有管理权限的 sudo 用户</li><li>RHEL 9 DVD 或 ISO 文件</li></ul><h3 id="_1-挂载-rhel-9-iso-文件或-dvd" tabindex="-1">1）挂载 RHEL 9 ISO 文件或 DVD <a class="header-anchor" href="#_1-挂载-rhel-9-iso-文件或-dvd" aria-label="Permalink to 1）挂载 RHEL 9 ISO 文件或 DVD">​</a></h3><p>我们假设 RHEL 9 iso 文件已经被复制到系统中。运行下面的挂载命令，将 ISO 文件挂载到 <code>/opt/repo</code> 文件夹。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo mkdir /var/repo</span></span>
<span class="line"><span>$ sudo mount -o loop rhel-baseos-9.0-x86_64-dvd.iso /var/repo/</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Mount-RHEL9-ISO-File-Command.png" alt="Mount-RHEL9-ISO-File-Command"></p><p>如果是 DVD 光盘，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo mount /dev/sr0 /var/repo/</span></span></code></pre></div><h3 id="_2-在-etc-yum-repos-d-目录中创建仓库文件" tabindex="-1">2）在 /etc/yum.repos.d/ 目录中创建仓库文件 <a class="header-anchor" href="#_2-在-etc-yum-repos-d-目录中创建仓库文件" aria-label="Permalink to 2）在 /etc/yum.repos.d/ 目录中创建仓库文件">​</a></h3><p>在 <code>/etc/yum.repos.d/</code> 目录下创建一个名为 “rhel9-local.repo\` 的仓库文件，内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo vi /etc/yum.repos.d/rhel9-local.repo</span></span>
<span class="line"><span>[Local-BaseOS]</span></span>
<span class="line"><span>name=Red Hat Enterprise Linux 9 - BaseOS</span></span>
<span class="line"><span>metadata_expire=-1</span></span>
<span class="line"><span>gpgcheck=1</span></span>
<span class="line"><span>enabled=1</span></span>
<span class="line"><span>baseurl=file:///var/repo//BaseOS/</span></span>
<span class="line"><span>gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-redhat-release</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Local-AppStream]</span></span>
<span class="line"><span>name=Red Hat Enterprise Linux 9 - AppStream</span></span>
<span class="line"><span>metadata_expire=-1</span></span>
<span class="line"><span>gpgcheck=1</span></span>
<span class="line"><span>enabled=1</span></span>
<span class="line"><span>baseurl=file:///var/repo//AppStream/</span></span>
<span class="line"><span>gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-redhat-release</span></span></code></pre></div><p>保存并关闭该文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/RHEL8-Local-Repo-File.png" alt="RHEL8-Local-Repo-File"></p><h3 id="_3-刷新-yum-dnf-和订阅管理器的缓存" tabindex="-1">3）刷新 Yum/DNF 和订阅管理器的缓存 <a class="header-anchor" href="#_3-刷新-yum-dnf-和订阅管理器的缓存" aria-label="Permalink to 3）刷新 Yum/DNF 和订阅管理器的缓存">​</a></h3><p>执行以下命令来清理 Yum 或 DNF 和订阅管理器的缓存。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf clean all</span></span>
<span class="line"><span>$ sudo subscription-manager clean</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/DNF-Subscription-Manager-Clean.png" alt="DNF-Subscription-Manager-Clean"></p><p>在上面的输出中，我们得到一个警告信息 <code>This system is not registered with an entitlement</code>（系统没有注册权限）。所以，为了抑制这个警告信息，编辑文件 <code>/etc/yum/pluginconf.d/subscription-manager.conf</code>，将参数 <code>enabled=1</code> 改为 <code>enabled=0</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo vi /etc/yum/pluginconf.d/subscription-manager.conf</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Disable-Subscription-Parameter-RHEL-9.png" alt="Disable-Subscription-Parameter-RHEL-9"></p><p>保存并退出该文件。</p><h3 id="_4-使用本地仓库安装软件包" tabindex="-1">4）使用本地仓库安装软件包 <a class="header-anchor" href="#_4-使用本地仓库安装软件包" aria-label="Permalink to 4）使用本地仓库安装软件包">​</a></h3><p>现在我们都准备好测试我们的本地仓库了。运行下面的命令来查看配置仓库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf repolist</span></span></code></pre></div><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/DNF-Repolist-RHEL-9.png" alt="DNF-Repolist-RHEL-9"></p><p>现在，试试用 <code>dnf</code> 命令通过上面配置的本地仓库安装软件包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install nfs-utils</span></span></code></pre></div><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Install-RPM-Package-via-local-repo-rhel9.png" alt="Install-RPM-Package-via-local-repo-rhel9"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Package-Installation-Completion-RHEL9-DNF-Command.png" alt="Package-Installation-Completion-RHEL9-DNF-Command"></p><p>完美，上述输出证实了 <code>nfs-utils</code> 包及其依赖项已经通过本地配置的 Yum 或 DNF 仓库成功安装。</p><p>这就是本指南的全部内容。我希望你觉得它有参考价值。请在下面的评论区发表你的疑问和反馈。</p><hr>`,39)),t("p",null,[a[1]||(a[1]=e("via: ")),n(s,{href:"https://www.linuxtechi.com/create-local-yum-dnf-repository-rhel/"},{default:p(()=>a[0]||(a[0]=[e("https://www.linuxtechi.com/create-local-yum-dnf-repository-rhel/")])),_:1})]),t("p",null,[a[6]||(a[6]=e("作者：")),n(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:p(()=>a[2]||(a[2]=[e("Pradeep Kumar")])),_:1}),a[7]||(a[7]=e(" 选题：")),n(s,{href:"https://github.com/lkxed"},{default:p(()=>a[3]||(a[3]=[e("lkxed")])),_:1}),a[8]||(a[8]=e(" 译者：")),n(s,{href:"https://github.com/geekpi"},{default:p(()=>a[4]||(a[4]=[e("geekpi")])),_:1}),a[9]||(a[9]=e(" 校对：")),n(s,{href:"https://github.com/wxy"},{default:p(()=>a[5]||(a[5]=[e("wxy")])),_:1})]),t("p",null,[a[12]||(a[12]=e("本文由 ")),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>a[10]||(a[10]=[e("LCTT")])),_:1}),a[13]||(a[13]=e(" 原创编译，")),n(s,{href:"https://linux.cn/"},{default:p(()=>a[11]||(a[11]=[e("Linux中国")])),_:1}),a[14]||(a[14]=e(" 荣誉推出"))])])}const k=l(c,[["render",u]]);export{w as __pageData,k as default};
